mapper.select:
SELECT r.czrq, c.czyxm, r.sm, r.ztid, r.czip, r.czmk
FROM sys_rz r
LEFT JOIN sys_czydm c ON r.czydm=c.czydm
WHERE 1=1
 AND r.zxtid = #{zxtid} 
 AND r.ztid = #{ztid} 
 AND r.czydm = #{czydm} 
 AND r.czrq >= #{beginDate} 
 AND r.czrq <= #{endDate} 
ORDER BY r.czrq DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM sys_rz r
WHERE 1=1
 AND r.zxtid = #{zxtid} 
 AND r.ztid = #{ztid} 
 AND r.czydm = #{czydm} 
 AND r.czrq >= #{beginDate} 
 AND r.czrq <= #{endDate}
